```java
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;

import java.time.Duration;

import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Calculator Tests")
class CalculatorTest {

    private Calculator calculator;

    @BeforeEach
    void setUp() {
        calculator = new Calculator();
        System.out.println("Setting up calculator for test");
    }

    @AfterEach
    void tearDown() {
        calculator = null;
        System.out.println("Cleaning up after test");
    }

    @BeforeAll
    static void beforeAll() {
        System.out.println("Starting Calculator test suite");
    }

    @AfterAll
    static void afterAll() {
        System.out.println("Finished Calculator test suite");
    }

    @Nested
    @DisplayName("Addition Tests")
    class AdditionTests {

        @Test
        @DisplayName("Should add two positive numbers correctly")
        void shouldAddPositiveNumbers() {
            int result = calculator.add(5, 3);
            assertEquals(8, result, "5 + 3 should be 8");
        }

        @Test
        @DisplayName("Should add positive and negative numbers correctly")
        void shouldAddPositiveAndNegative() {
            int result = calculator.add(5, -3);
            assertEquals(2, result, "5 + (-3) should be 2");
        }

        @Test
        @DisplayName("Should add zero correctly")
        void shouldAddZero() {
            assertAll("Zero addition tests",
                () -> assertEquals(5, calculator.add(5, 0)),
                () -> assertEquals(5, calculator.add(0, 5)),
                () -> assertEquals(0, calculator.add(0, 0))
            );
        }

        @ParameterizedTest(name = "{0} + {1} = {2}")
        @CsvSource({
            "1, 1, 2",
            "2, 3, 5",
            "10, -5, 5",
            "-1, -1, -2"
        })
        @DisplayName("Parameterized addition tests")
        void shouldAddNumbers(int a, int b, int expected) {
            assertEquals(expected, calculator.add(a, b));
        }
    }

    @Nested
    @DisplayName("Division Tests")
    class DivisionTests {

        @Test
        @DisplayName("Should divide two numbers correctly")
        void shouldDivideNumbers() {
            int result = calculator.divide(10, 2);
            assertEquals(5, result, "10 / 2 should be 5");
        }

        @Test
        @DisplayName("Should throw exception when dividing by zero")
        void shouldThrowWhenDividingByZero() {
            Exception exception = assertThrows(IllegalArgumentException.class, 
                () -> calculator.divide(10, 0));
            assertEquals("Division by zero", exception.getMessage());
        }

        @Test
        @DisplayName("Should handle division rounding correctly")
        void shouldHandleDivisionRounding() {
            int result = calculator.divide(10, 3);
            assertEquals(3, result, "Integer division should truncate");
        }
    }

    @Nested
    @DisplayName("Power Tests")
    class PowerTests {

        @Test
        @DisplayName("Should calculate power correctly")
        void shouldCalculatePower() {
            double result = calculator.power(2, 3);
            assertEquals(8.0, result, 0.001, "2^3 should be 8");
        }

        @ParameterizedTest
        @ValueSource(doubles = {0, 1, 2, 3, 4})
        @DisplayName("Any number to power 0 should be 1")
        void shouldReturnOneForPowerZero(double base) {
            double result = calculator.power(base, 0);
            assertEquals(1.0, result, 0.001);
        }

        @Test
        @DisplayName("Should handle negative exponents")
        void shouldHandleNegativeExponent() {
            double result = calculator.power(2, -1);
            assertEquals(0.5, result, 0.001, "2^-1 should be 0.5");
        }
    }

    @Nested
    @DisplayName("Factorial Tests")
    class FactorialTests {

        @Test
        @DisplayName("Should calculate factorial correctly")
        void shouldCalculateFactorial() {
            assertAll("Factorial values",
                () -> assertEquals(1, calculator.factorial(0)),
                () -> assertEquals(1, calculator.factorial(1)),
                () -> assertEquals(2, calculator.factorial(2)),
                () -> assertEquals(6, calculator.factorial(3)),
                () -> assertEquals(24, calculator.factorial(4)),
                () -> assertEquals(120, calculator.factorial(5))
            );
        }

        @Test
        @DisplayName("Should throw exception for negative numbers")
        void shouldThrowForNegativeNumbers() {
            assertThrows(IllegalArgumentException.class, 
                () -> calculator.factorial(-1),
                "Factorial of negative number should throw exception"
            );
        }

        @Test
        @DisplayName("Should complete within reasonable time")
        void shouldCompleteWithinTime() {
            assertTimeout(Duration.ofMillis(10), () -> {
                calculator.factorial(20);
            });
        }
    }

    @Test
    @Tag("performance")
    @DisplayName("Performance test for multiple operations")
    void testMultipleOperationsPerformance() {
        assertTimeout(Duration.ofMillis(100), () -> {
            for (int i = 0; i < 1000; i++) {
                calculator.add(i, i);
                calculator.multiply(i, i);
                calculator.power(i % 10, 2);
            }
        });
    }

    @Test
    @Disabled("Demonstration of disabled test")
    @DisplayName("This test is disabled for demonstration")
    void testNotImplemented() {
        fail("This test should not run");
    }
}
```

