        showStandardStreams = true
        showExceptions = true
        showCauses = true
        showStackTraces = true
        exceptionFormat = 'full'

        // Print test execution times
        afterSuite { desc, result ->
            if (!desc.parent) {
                println "\nTest Results: ${result.resultType}"
                println "Tests run: ${result.testCount}, " +
                    "Failures: ${result.failedTestCount}, " +
                    "Skipped: ${result.skippedTestCount}"
                println "Time: ${(result.endTime - result.startTime) / 1000}s\n"
            }
        }
    }

    // Test system properties
    systemProperties = [
        'environment': System.getProperty('environment', 'test'),
        'browser': System.getProperty('browser', 'chrome'),
        'headless': System.getProperty('headless', 'true'),
