import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.DisplayName;
import static org.junit.jupiter.api.Assertions.*;

@DisplayName("Calculator Tests")
class CalculatorTest {

    private final Calculator calculator = new Calculator();

    @Test
    @DisplayName("Addition of two positive numbers")
    void additionWithPositiveNumbers() {
        // Arrange
        int a = 5;
        int b = 3;

        // Act
        int result = calculator.add(a, b);

        // Assert
        assertEquals(8, result, "5 + 3 should equal 8");
    }

    @Test
    @DisplayName("Addition with negative numbers")
    void additionWithNegativeNumbers() {
        assertEquals(-2, calculator.add(-5, 3), "-5 + 3 should equal -2");
        assertEquals(-8, calculator.add(-5, -3), "-5 + -3 should equal -8");
    }

    @Test
    @DisplayName("Subtraction of two numbers")
    void subtraction() {
        assertEquals(2, calculator.subtract(5, 3), "5 - 3 should equal 2");
        assertEquals(-2, calculator.subtract(3, 5), "3 - 5 should equal -2");
    }

    @Test
    @DisplayName("Multiplication of two numbers")
    void multiplication() {
        assertEquals(15, calculator.multiply(5, 3), "5 * 3 should equal 15");
        assertEquals(0, calculator.multiply(5, 0), "5 * 0 should equal 0");
    }

    @Test
    @DisplayName("Division of two numbers")
    void division() {
        assertEquals(2, calculator.divide(10, 5), "10 / 5 should equal 2");
        assertEquals(3, calculator.divide(10, 3), "10 / 3 should equal 3 (integer division)");
    }

    @Test
    @DisplayName("❌ Division by zero should throw exception")
    void divisionByZero() {
        assertThrows(ArithmeticException.class, 
