**Using Assertions Effectively:**

```java
import static org.junit.jupiter.api.Assertions.*;

class AssertionExamplesTest {

    @Test
    void testAllAssertionTypes() {
        // Equality
        assertEquals(4, 2 + 2, "Optional message");
        assertNotEquals(5, 2 + 2);

        // Booleans
        assertTrue(10 > 5);
        assertFalse(10 < 5);

        // Null checks
        Object obj = null;
        assertNull(obj);
        obj = new Object();
        assertNotNull(obj);

        // Identity (reference equality)
        String s1 = "hello";
        String s2 = "hello";
        assertSame(s1, s2);  // String interning

        String s3 = new String("hello");
        assertNotSame(s1, s3);  // Different objects

        // Arrays
        int[] expected = {1, 2, 3};
        int[] actual = {1, 2, 3};
        assertArrayEquals(expected, actual);

        // Iterables
        List<String> list1 = Arrays.asList("a", "b", "c");
        List<String> list2 = Arrays.asList("a", "b", "c");
        assertIterableEquals(list1, list2);

        // Exceptions
        assertThrows(IllegalArgumentException.class, () -> {
            throw new IllegalArgumentException("test");
        });

        // Timeouts
        assertTimeout(Duration.ofMillis(100), () -> {
            Thread.sleep(50);
        });

        // Grouped assertions
        assertAll("group",
            () -> assertEquals(1, 1),
            () -> assertEquals(2, 2),
            () -> assertEquals(3, 3)
        );
    }
}
