**Dynamic Tests:**

```java
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.TestFactory;
import java.util.stream.Stream;

class DynamicTestClass {

    @TestFactory
    @DisplayName("Dynamic tests")
    Stream<DynamicTest> dynamicTests() {
        return Stream.of(1, 2, 3, 4, 5)
            .map(number -> DynamicTest.dynamicTest(
                "Test for " + number,
                () -> assertTrue(number > 0)
            ));
    }

    @TestFactory
    @DisplayName("Dynamic tests from data")
    Stream<DynamicTest> dynamicTestsFromData() {
        List<TestCase> testCases = Arrays.asList(
            new TestCase(2, 3, 5),
            new TestCase(5, 5, 10),
            new TestCase(10, -5, 5)
        );

        return testCases.stream()
            .map(tc -> DynamicTest.dynamicTest(
                String.format("%d + %d = %d", tc.a, tc.b, tc.expected),
                () -> assertEquals(tc.expected, tc.a + tc.b)
            ));
    }

    static class TestCase {
        int a, b, expected;
        TestCase(int a, int b, int expected) {
            this.a = a; this.b = b; this.expected = expected;
        }
    }
}
