        User updated = userService.findUserById(testUser.getId());
        assertEquals("New Name", updated.getName());
    }

    // No need to recreate testUser for each test
}
```

**6. Test Edge Cases**

```java
class EdgeCaseTest {

    @Test
    void shouldHandleNullInput() {
        assertThrows(IllegalArgumentException.class, 
            () -> userService.createUser(null, "name"));
    }

    @Test
    void shouldHandleEmptyString() {
        assertThrows(IllegalArgumentException.class, 
            () -> userService.createUser("", "name"));
    }

    @Test
    void shouldHandleVeryLongInput() {
        String longEmail = "a".repeat(1000) + "@example.com";
        User user = userService.createUser(longEmail, "name");
        assertNotNull(user);
    }

    @Test
    void shouldHandleBoundaryValues() {
        assertEquals(Integer.MAX_VALUE, calculator.add(Integer.MAX_VALUE, 0));
        assertThrows(ArithmeticException.class, 
            () -> calculator.add(Integer.MAX_VALUE, 1));  // Overflow
    }
}
```

**7. Use Appropriate Assertions**

```java
// BAD - Using assertTrue for everything
assertTrue(a == b);
assertTrue(list.contains(item));
assertTrue(obj != null);

// GOOD - Specific assertions
assertEquals(a, b);
assertTrue(list.contains(item));  // This one is correct
assertNotNull(obj);
```

**8. Keep Tests Readable**

```java
// BAD - Hard to understand
@Test
void t() {
    Calculator c = new Calculator();
    int x = c.add(5, 3);
    assert x == 8;
}

// GOOD - Self-documenting
@Test
@DisplayName("Addition of 5 and 3 should return 8")
void addition_shouldReturnSum() {
    Calculator calculator = new Calculator();
    int sum = calculator.add(5, 3);
    assertEquals(8, sum, "5 + 3 should equal 8");
}
```

**9. Don't Test Implementation Details**

```java
// BAD - Testing private method through reflection or internal state
@Test
void testPrivateMethod() throws Exception {
    Method method = MyClass.class.getDeclaredMethod("privateMethod");
    method.setAccessible(true);
    Object result = method.invoke(new MyClass());
    assertEquals("expected", result);
}

// GOOD - Test public behavior
@Test
void testPublicBehavior() {
    MyClass obj = new MyClass();
    String result = obj.publicMethodThatUsesPrivateMethod();
    assertEquals("expected", result);
}
```

**10. Follow the F.I.R.S.T. Principles**

| Principle | Meaning | How to Achieve |
|-----------|---------|----------------|
| **Fast** | Tests run quickly | Mock external dependencies, avoid I/O |
| **Independent** | Tests don't depend on each other | Fresh setup for each test |
| **Repeatable** | Same result every time | No random data, controlled environment |
| **Self-Validating** | Tests pass/fail clearly | Use assertions, no manual checking |
| **Timely** | Written at the right time | Write tests before or with code |

**Test Organization Checklist:**

- [ ] Test class name corresponds to production class
- [ ] Test methods are independent and can run in any order
- [ ] Setup and teardown methods are used appropriately
- [ ] Tests are grouped logically (using @Nested if needed)
- [ ] Test names are descriptive and follow a consistent pattern
- [ ] Each test verifies one specific behavior
- [ ] Edge cases and error conditions are tested
- [ ] Tests are fast and don't depend on external systems
- [ ] Assertions are specific and include meaningful messages
- [ ] Code coverage is adequate (but not the only metric)

**Example: Well-Organized Test Class**

```java
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@DisplayName("Order Service Tests")
@Tag("unit")
class OrderServiceTest {

    private OrderService orderService;
    private PaymentService paymentService;
    private InventoryService inventoryService;
    private Order testOrder;

    @BeforeEach
    void setUp() {
        paymentService = mock(PaymentService.class);
        inventoryService = mock(InventoryService.class);
        orderService = new OrderService(paymentService, inventoryService);

        testOrder = new Order("user123");
        testOrder.addItem(new Item("product1", 2, 10.0));
    }

    @Nested
    @DisplayName("Order Creation")
    class CreateOrderTests {

        @Test
        @DisplayName("Should create order with valid items")
        void createOrder_withValidItems_shouldSucceed() {
            when(inventoryService.checkAvailability("product1", 2)).thenReturn(true);

            Order created = orderService.createOrder(testOrder);

            assertNotNull(created);
            assertNotNull(created.getId());
            assertEquals(OrderStatus.PENDING, created.getStatus());
        }

        @Test
        @DisplayName("Should throw exception when items out of stock")
        void createOrder_withOutOfStock_shouldThrow() {
            when(inventoryService.checkAvailability("product1", 2)).thenReturn(false);

            assertThrows(OutOfStockException.class, 
                () -> orderService.createOrder(testOrder));
        }

        @Test
        @DisplayName("Should throw exception when order has no items")
        void createOrder_withEmptyOrder_shouldThrow() {
            Order emptyOrder = new Order("user123");

            assertThrows(IllegalArgumentException.class,
                () -> orderService.createOrder(emptyOrder));
        }
    }

    @Nested
    @DisplayName("Order Payment")
    class PaymentTests {

        @Test
        @DisplayName("Should process payment successfully")
        void processPayment_withValidCard_shouldSucceed() {
            when(paymentService.charge(anyDouble(), anyString())).thenReturn(true);

