**Mastering Essential Assertions:**

JUnit provides a comprehensive set of assertion methods. Here's a deep dive into each category with practical examples.

**1. assertEquals and assertNotEquals**

The most frequently used assertions for comparing values.

```java
import static org.junit.jupiter.api.Assertions.*;

class EqualityAssertionsTest {

    @Test
    void testEquality() {
        // Primitive types
        assertEquals(8, 5 + 3, "5 + 3 should equal 8");

        // Strings
        String actual = "Hello World".toUpperCase();
        assertEquals("HELLO WORLD", actual, 
            "String should be uppercase");

        // With delta for floating point
        double pi = 22.0 / 7.0;
        assertEquals(3.142857, pi, 0.001, 
            "Pi approximation should be close");

        // Objects (requires proper equals() implementation)
        User user1 = new User("john@test.com");
        User user2 = new User("john@test.com");
        assertEquals(user1, user2, 
            "Users with same email should be equal");

        // Not equal
        assertNotEquals(5, 10, "5 and 10 should not be equal");

        // Different object types
        assertNotEquals("5", 5, "String and int should not be equal");
    }

    @Test
    void testMultipleDataTypes() {
        // Boolean
        assertEquals(true, 5 > 3);

        // Char
        assertEquals('A', 65); // ASCII comparison

        // Long
        assertEquals(1000000L, 1000L * 1000L);

        // Double with delta
        double result = 10.0 / 3.0;
        assertEquals(3.33333, result, 0.0001);
    }
}
```

**2. assertTrue and assertFalse**

For verifying boolean conditions.

```java
class BooleanAssertionsTest {

    @Test
    void testBooleanConditions() {
        // Simple condition
        int age = 25;
        assertTrue(age >= 18, "User should be adult");
        assertFalse(age < 13, "User should not be a child");

        // Method calls
        List<String> list = Arrays.asList("a", "b", "c");
        assertTrue(list.contains("b"), 
            "List should contain 'b'");
        assertFalse(list.contains("z"), 
            "List should not contain 'z'");

        // Complex conditions
        User user = new User("john@test.com", "John", 30);
        assertTrue(
            user.isActive() && user.hasVerifiedEmail(),
            "User should be active and verified"
        );

        // String checks
        String text = "Hello World";
        assertTrue(text.startsWith("Hello"), 
            "Text should start with Hello");
        assertFalse(text.contains("Goodbye"), 
            "Text should not contain Goodbye");

        // Collection checks
        List<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);
        assertTrue(numbers.stream().allMatch(n -> n > 0),
            "All numbers should be positive");
    }
}
```

**3. assertNull and assertNotNull**

For verifying null/non-null values.

```java
class NullAssertionsTest {

    private UserService userService = new UserService();

    @Test
    void testNullChecks() {
        // Verify object exists
        User user = userService.findUserById(123);
        assertNotNull(user, 
            "User with ID 123 should exist");

        // Verify optional field is null
        assertNull(user.getMiddleName(), 
            "Middle name should be null for this user");

        // Verify error cases
        User nonExistentUser = userService.findUserById(99999);
        assertNull(nonExistentUser, 
            "Non-existent user should return null");

        // Chain assertions
        assertNotNull(user.getEmail(), 
            "Email should not be null");
        assertNotNull(user.getCreatedDate(), 
            "Created date should not be null");
    }

    @Test
    void testNullWithCollections() {
        List<User> users = userService.getAllUsers();

        // Collection itself shouldn't be null
        assertNotNull(users, 
            "User list should not be null");

        // But could be empty
        if (!users.isEmpty()) {
            assertNotNull(users.get(0).getId(),
                "First user should have ID");
        }
    }
}
```

**4. assertSame and assertNotSame**

For verifying object identity (reference equality).

```java
class IdentityAssertionsTest {

    @Test
    void testObjectIdentity() {
        String str1 = "hello";
        String str2 = "hello";
        String str3 = new String("hello");

        // String interning - same reference
        assertSame(str1, str2, 
            "String literals should share reference");

        // New String creates new object
        assertNotSame(str1, str3, 
            "new String() creates new object");

        // But they are equal in value
        assertEquals(str1, str3, 
            "Values should be equal");

        // Custom objects
        User user1 = new User("john@test.com");
        User user2 = user1;  // Same reference
        User user3 = new User("john@test.com");  // Different object

        assertSame(user1, user2, 
            "Should be same reference");
        assertNotSame(user1, user3, 
            "Different objects even if equal values");
    }

    @Test
    void testSingletonPattern() {
        DatabaseConnection conn1 = DatabaseConnection.getInstance();
        DatabaseConnection conn2 = DatabaseConnection.getInstance();

        // Singleton should return same instance
        assertSame(conn1, conn2, 
            "Singleton should return same instance");
    }
}
```

**5. fail Method**

For explicitly failing a test.

```java
class FailAssertionsTest {

    @Test
    void testFailWhenConditionNotMet() {
        boolean condition = checkSomeCondition();

        if (!condition) {
            fail("Condition not met - test cannot proceed");
        }

        // Continue with test if condition met
    }

    @Test
    void testExceptionHandling() {
        try {
            riskyOperation();
            // If we get here, no exception was thrown
            fail("Expected exception was not thrown");
        } catch (ExpectedException e) {
            // Expected, test passes
            assertEquals("specific error", e.getMessage());
        }
    }

    @Test
    void testNotImplemented() {
        // Mark test as not implemented yet
        fail("Test not implemented yet");
    }

    @Test
    void testUnreachableCode() {
        try {
            // Some operation
        } catch (Exception e) {
            fail("Should not throw exception", e);
        }
    }
}
```

**6. Asserting Arrays**

```java
class ArrayAssertionsTest {

    @Test
    void testArrayEquality() {
        int[] expected = {1, 2, 3, 4, 5};
        int[] actual = {1, 2, 3, 4, 5};

        // Compare arrays by content
        assertArrayEquals(expected, actual, 
            "Arrays should have same content");

        // Different arrays
        int[] different = {1, 2, 3, 4, 6};
        assertArrayEquals(expected, different); // This would fail

        // Multi-dimensional arrays
        int[][] expected2D = {{1, 2}, {3, 4}};
        int[][] actual2D = {{1, 2}, {3, 4}};
        assertArrayEquals(expected2D, actual2D);

        // Object arrays
        String[] expectedStrings = {"a", "b", "c"};
        String[] actualStrings = {"a", "b", "c"};
        assertArrayEquals(expectedStrings, actualStrings);
    }

    @Test
    void testArrayConditions() {
        int[] numbers = {1, 2, 3, 4, 5};

        // Check array length
        assertEquals(5, numbers.length, 
            "Array should have 5 elements");

        // Check specific element
        assertEquals(3, numbers[2], 
            "Third element should be 3");

        // Partial array comparison
        int[] firstThree = Arrays.copyOf(numbers, 3);
        int[] expectedFirstThree = {1, 2, 3};
        assertArrayEquals(expectedFirstThree, firstThree);
    }
}
```

**7. Asserting Collections**

```java
class CollectionAssertionsTest {

    @Test
    void testListEquality() {
        List<String> expected = Arrays.asList("a", "b", "c");
        List<String> actual = Arrays.asList("a", "b", "c");

        // Compare lists
        assertIterableEquals(expected, actual, 
            "Lists should be equal");

        // Order matters
        List<String> differentOrder = Arrays.asList("c", "b", "a");
        assertIterableEquals(expected, differentOrder); // Would fail

        // Check content ignoring order
        assertTrue(expected.containsAll(actual) && actual.containsAll(expected));
    }

    @Test
    void testSetEquality() {
        Set<String> expected = new HashSet<>(Arrays.asList("a", "b", "c"));
        Set<String> actual = new HashSet<>(Arrays.asList("c", "b", "a"));

        // Sets are equal regardless of iteration order
        assertEquals(expected, actual);
    }

    @Test
    void testMapEquality() {
        Map<String, Integer> expected = new HashMap<>();
        expected.put("a", 1);
        expected.put("b", 2);

        Map<String, Integer> actual = new HashMap<>();
        actual.put("b", 2);
        actual.put("a", 1);

        // Maps are equal regardless of iteration order
        assertEquals(expected, actual, 
            "Maps should be equal");

        // Check specific entry
        assertEquals(1, actual.get("a"));
    }

    @Test
    void testCollectionConditions() {
        List<String> list = Arrays.asList("a", "b", "c");

        // Check contains
        assertTrue(list.contains("b"), 
            "List should contain 'b'");

        // Check size
        assertEquals(3, list.size(), 
            "List should have 3 elements");

        // Check not empty
        assertFalse(list.isEmpty(), 
            "List should not be empty");
    }
}
```

**8. Asserting Exceptions**

```java
class ExceptionAssertionsTest {

    @Test
    void testExceptionThrown() {
        // Assert that exception is thrown
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            new Account().withdraw(-100);
        });

        // Verify exception message
        assertEquals("Amount must be positive", exception.getMessage());
    }

    @Test
    void testNoExceptionThrown() {
        // Assert that no exception is thrown
        assertDoesNotThrow(() -> {
            new Account().withdraw(100);
        });
    }

    @Test
    void testSpecificExceptionType() {
        // Verify correct exception type
        assertThrows(ArithmeticException.class, () -> {
            int result = 10 / 0;
        });
    }

    @Test
    void testExceptionWithMessage() {
        // Verify exception message contains text
        Exception exception = assertThrows(IllegalStateException.class, () -> {
            throw new IllegalStateException("Invalid state for operation");
        });

        assertTrue(exception.getMessage().contains("Invalid state"));
    }

    @Test
    void testMultipleExceptions() {
        // Test that different inputs cause different exceptions
        assertAll("Exception tests",
            () -> assertThrows(IllegalArgumentException.class, 
                () -> new Account().withdraw(-1)),
            () -> assertThrows(IllegalStateException.class, 
                () -> new Account().withdrawFromClosedAccount()),
            () -> assertDoesNotThrow(
                () -> new Account().withdraw(100))
        );
    }
}
```

**9. Timeout Assertions**

```java
import java.time.Duration;

class TimeoutAssertionsTest {

    @Test
    void testTimeout() {
        // Assert that execution completes within specified time
        assertTimeout(Duration.ofMillis(100), () -> {
            // Code that should complete within 100ms
            Thread.sleep(50);
        });
    }

    @Test
    void testTimeoutWithResult() {
        // Assert timeout and get result
        String result = assertTimeout(Duration.ofMillis(100), () -> {
            return expensiveOperation();
        });

        assertEquals("expected", result);
    }

    @Test
    void testTimeoutPreemptively() {
        // Preemptively fails if timeout exceeded (aborts the thread)
        assertTimeoutPreemptively(Duration.ofMillis(100), () -> {
            // This will be aborted if it takes too long
            potentiallyInfiniteLoop();
        });
    }

    @Test
    void testPerformanceWithTimeout() {
        // Verify operation meets performance requirements
        assertTimeout(Duration.ofSeconds(1), () -> {
            for (int i = 0; i < 1000; i++) {
                calculator.add(i, i);
            }
        });
    }
}
```

**10. Grouped Assertions with assertAll**

```java
class GroupedAssertionsTest {

    @Test
    void testUserProperties() {
        User user = new User("john@example.com", "John Doe", 30);

        // All assertions run, even if some fail
        assertAll("User properties",
            () -> assertEquals("john@example.com", user.getEmail()),
            () -> assertEquals("John Doe", user.getName()),
            () -> assertEquals(30, user.getAge()),
            () -> assertTrue(user.isActive()),
            () -> assertNotNull(user.getId())
        );
    }

    @Test
    void testOrderProperties() {
        Order order = createTestOrder();

        // Group assertions with nested assertAll
        assertAll("Order validation",
            () -> assertNotNull(order.getId()),
            () -> assertFalse(order.getItems().isEmpty()),
            () -> assertAll("Order totals",
                () -> assertEquals(100.0, order.getSubtotal()),
                () -> assertEquals(10.0, order.getTax()),
                () -> assertEquals(110.0, order.getTotal())
            ),
            () -> assertEquals(OrderStatus.PENDING, order.getStatus())
        );
    }

    @Test
    void testMultipleValidations() {
        List<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);

        assertAll("List validations",
            () -> assertEquals(5, numbers.size()),
            () -> assertTrue(numbers.contains(3)),
            () -> assertFalse(numbers.contains(6)),
            () -> assertIterableEquals(Arrays.asList(1, 2, 3, 4, 5), numbers)
        );
    }
}
