                () -> assertTrue(results.stream().allMatch(p -> 
                    p.getCategory().equals("Electronics"))),
                () -> assertTrue(results.stream().anyMatch(p -> 
                    p.getName().equals("Laptop")))
            );
        }

        @Test
        @DisplayName("Should return empty list for no matches")
        void shouldReturnEmptyForNoMatches() {
            List<Product> results = productService.searchProducts("Nonexistent");

            assertNotNull(results);
            assertTrue(results.isEmpty());
            assertEquals(0, results.size());
        }

        @Test
        @DisplayName("Should handle null search term")
        void shouldHandleNullSearch() {
            List<Product> results = productService.searchProducts(null);

            assertNotNull(results);
            assertTrue(results.isEmpty());
        }

        @Test
        @DisplayName("Should sort results by relevance (price low to high)")
        void shouldSortResultsByPrice() {
            List<Product> results = productService.searchProducts("Electronics");

            // Verify sorting
            for (int i = 0; i < results.size() - 1; i++) {
                assertTrue(results.get(i).getPrice() <= results.get(i + 1).getPrice(),
                    "Products should be sorted by price ascending");
            }
        }
    }

    // ==================== CART SERVICE TESTS ====================

    @Nested
    @DisplayName("Shopping Cart Tests")
    class ShoppingCartTests {

