            // Assert
            assertNotNull(cart);
            assertEquals(1, cart.getItemCount());
            assertEquals(1, cart.getUniqueItemCount());
            assertEquals(999.99, cart.getSubtotal());

            CartItem item = cart.findItem(laptop.getId());
            assertNotNull(item);
            assertEquals(1, item.getQuantity());
            assertEquals(999.99, item.getUnitPrice());
            assertEquals(999.99, item.getTotalPrice());
        }

        @Test
        @DisplayName("Should add multiple items to cart")
        void shouldAddMultipleItems() {
            // Act
            cartService.addToCart(user.getId(), laptop.getId(), 2);
            cartService.addToCart(user.getId(), mouse.getId(), 3);
            Cart cart = cartService.getCart(user.getId());

            // Assert
            assertAll("Cart totals",
                () -> assertEquals(5, cart.getItemCount()),
