                () -> assertEquals(208.995, cart.getTax(), 0.01),
                () -> assertEquals(2298.945, cart.getTotal(), 0.01)
            );

            // Check laptop item
            CartItem laptopItem = cart.findItem(laptop.getId());
            assertNotNull(laptopItem);
            assertEquals(2, laptopItem.getQuantity());
