            cartService.removeFromCart(user.getId(), laptop.getId(), 1);
            Cart cart = cartService.getCart(user.getId());

            // Assert
            assertEquals(2, cart.getItemCount()); // 1 laptop + 1 mouse
            assertEquals(1029.98, cart.getSubtotal(), 0.01);

            // Act - remove all laptops
            cartService.removeFromCart(user.getId(), laptop.getId(), 1);
            cart = cartService.getCart(user.getId());

            assertEquals(1, cart.getItemCount());
            assertEquals(29.99, cart.getSubtotal(), 0.01);
        }

        @Test
