                () -> assertNotNull(order),
                () -> assertNotNull(order.getId()),
                () -> assertEquals(user.getId(), order.getUserId()),
                () -> assertEquals(OrderStatus.PENDING, order.getStatus()),
                () -> assertNotNull(order.getOrderDate()),
                () -> assertEquals(1059.97, order.getSubtotal(), 0.01),
