            Order order = orderService.createOrderFromCart(user.getId());
            paymentService.processPayment(order.getId(), 
                PaymentMethod.CREDIT_CARD, "4111111111111111");

            // Act
            boolean shipped = orderService.shipOrder(order.getId(), "TRACK123");

            // Assert
            assertTrue(shipped);

            Order shippedOrder = orderService.getOrder(order.getId());
            assertEquals(OrderStatus.SHIPPED, shippedOrder.getStatus());
            assertEquals("TRACK123", shippedOrder.getTrackingNumber());
