        }

        @Test
        @DisplayName("Should not ship unpaid order")
        void shouldNotShipUnpaidOrder() {
            Order order = orderService.createOrderFromCart(user.getId());

            assertThrows(IllegalStateException.class,
                () -> orderService.shipOrder(order.getId(), "TRACK123")
            );
        }
    }
}
```

**Key Assertion Patterns in This Example:**

| Pattern | Example | Purpose |
|---------|---------|---------|
| **Null Checks** | `assertNotNull(registeredUser.getId())` | Verify required fields exist |
| **Value Equality** | `assertEquals(user.getEmail(), email)` | Verify data was saved correctly |
| **Range Checks** | `assertTrue(price > 0)` | Validate value ranges |
| **Collection Content** | `assertTrue(results.contains(product))` | Verify items in collections |
| **Exception Validation** | `assertThrows(...)` | Verify error handling |
| **State Transitions** | `assertEquals(OrderStatus.PAID, order.getStatus())` | Verify business rules |
| **Mathematical Accuracy** | `assertEquals(total, expected, 0.01)` | Handle floating point precision |
| **Business Rules** | `assertFalse(user.isAdmin())` | Verify default permissions |
| **Grouped Assertions** | `assertAll()` | Multiple related checks |
| **Timeouts** | `assertTimeout()` | Performance validation |

content.explanation:
**The Art of Good Assertions**

Well-written assertions are the difference between flaky, hard-to-debug tests and reliable, maintainable test suites.

**1. Provide Meaningful Messages**

Always include descriptive messages that help debug failures.

```java
// Bad
assertEquals(actual, expected);

// Good
assertEquals(expected, actual, 
    "User count should match after registration");

// Better - include context
assertEquals(expected, actual, 
    () -> String.format("User count after adding %d users should be %d", 
        newUsers, expected));

// Best - include actual values for comparison
assertTrue(age >= 18,
    () -> String.format("User age %d should be at least 18 for voting feature", age));
```

**2. One Logical Concept Per Test**

```java
// Bad - testing too many things
@Test
void testUser() {
    User user = userService.createUser(email, name, age);
    assertNotNull(user);
    assertEquals(email, user.getEmail());
    assertEquals(name, user.getName());
    assertTrue(user.canLogin());
    assertTrue(user.canPurchase());
}

// Good - focused tests
@Test
void createUser_shouldSetEmail() {
    User user = userService.createUser(email, name, age);
    assertEquals(email, user.getEmail(), "Email should match");
}

@Test
void createUser_shouldSetName() {
    User user = userService.createUser(email, name, age);
    assertEquals(name, user.getName(), "Name should match");
}

@Test
void createUser_shouldBeActive() {
    User user = userService.createUser(email, name, age);
    assertTrue(user.isActive(), "New user should be active");
}
```

**3. Test Both Positive and Negative Cases**

```java
@Test
void login_shouldSucceedWithValidCredentials() {
    boolean result = authService.login(validUser, validPass);
    assertTrue(result, "Login should succeed with valid credentials");
}

@Test
void login_shouldFailWithInvalidPassword() {
    boolean result = authService.login(validUser, wrongPass);
    assertFalse(result, "Login should fail with wrong password");
}

@Test
void login_shouldThrowExceptionWithNullUser() {
    assertThrows(IllegalArgumentException.class,
        () -> authService.login(null, "pass"),
        "Should throw exception for null user"
    );
}
```

**4. Use Appropriate Assertion Methods**

```java
// Bad - using assertTrue for everything
assertTrue(value == 5);
assertTrue(object.equals(expected));
assertTrue(list.contains(item));

// Good - use specific assertions
assertEquals(5, value, "Value should be 5");
assertEquals(expected, object, "Objects should be equal");
assertTrue(list.contains(item), "List should contain item");
```

**5. Be Careful with Floating Point**

```java
// Bad - floating point precision issues
assertEquals(0.1 + 0.2, 0.3);  // May fail!

// Good - use delta
assertEquals(0.3, 0.1 + 0.2, 0.0001, 
    "Floating point calculation should be accurate within delta");

// Better - use BigDecimal for precise calculations
BigDecimal result = new BigDecimal("0.1").add(new BigDecimal("0.2"));
assertEquals(new BigDecimal("0.3"), result);
```

**6. Assert Collections Properly**

```java
@Test
void testCollections() {
    List<String> actual = Arrays.asList("a", "b", "c");
    List<String> expected = Arrays.asList("a", "b", "c");

    // Check entire list equality
    assertIterableEquals(expected, actual, "Lists should be equal");

    // Check size
    assertEquals(3, actual.size(), "List should have 3 elements");

    // Check contains
    assertTrue(actual.contains("b"), "List should contain 'b'");

    // Check order matters
    List<String> unsorted = Arrays.asList("c", "a", "b");
    assertNotEquals(expected, unsorted, "Order matters in lists");
}
```

**7. Use assertAll for Multiple Related Checks**

```java
@Test
void testUserProperties() {
    User user = userService.findUser(123);

    assertAll("User validation",
        () -> assertNotNull(user, "User should exist"),
        () -> assertEquals("john@test.com", user.getEmail(), "Email mismatch"),
        () -> assertEquals("John Doe", user.getName(), "Name mismatch"),
        () -> assertTrue(user.isActive(), "User should be active"),
        () -> assertFalse(user.isBlocked(), "User should not be blocked")
    );
}
```

**8. Don't Assert Implementation Details**

```java
// Bad - asserting internal state
@Test
void testCache() {
    Cache cache = new Cache();
    cache.put("key", "value");

    // Asserting internal structure - fragile!
    assertTrue(cache.getInternalMap().containsKey("key"));
}

// Good - assert behavior
@Test
void testCache() {
    Cache cache = new Cache();
    cache.put("key", "value");

    assertEquals("value", cache.get("key"), "Should retrieve stored value");

    // Test expiration
    assertNull(cache.get("key"), "Value should expire");
}
```

**9. Use Lazy Messages for Expensive Construction**

```java
@Test
void testWithLazyMessage() {
    // Message lambda only executed if assertion fails
    assertEquals(expected, actual,
        () -> expensiveMessageConstruction(actual, expected));
}

private String expensiveMessageConstruction(Object actual, Object expected) {
    // Complex logging, API calls, etc.
    return String.format("Expected '%s' but was '%s'." +
        "Additional debug info: %s", expected, actual, getDebugInfo());
}
```

**10. Assertion Checklist**

Use this checklist when writing assertions:

- [ ] Does the assertion have a meaningful message?
- [ ] Does the assertion validate the behavior, not implementation?
- [ ] Is this the right assertion method (equality, true/false, null)?
- [ ] Have I considered both positive and negative cases?
- [ ] Is the test name descriptive enough?
- [ ] Does the assertion help debug when it fails?
- [ ] Have I handled floating point precision correctly?
- [ ] For collections, have I considered order and duplicates?
- [ ] Are my assertions independent of each other?
- [ ] Would someone understand why this test failed from the message?

**11. Common Assertion Anti-Patterns**

| Anti-Pattern | Example | Better Approach |
|--------------|---------|-----------------|
| **Asserting without message** | `assertTrue(result);` | `assertTrue(result, "User should be logged in");` |
| **Asserting too much** | One test with 20 assertions | Split into multiple focused tests |
| **Ignoring order in collections** | Assuming list order | Use sets if order doesn't matter |
| **Floating point without delta** | `assertEquals(0.1+0.2, 0.3);` | `assertEquals(0.3, 0.1+0.2, 0.0001);` |
| **Empty catch blocks** | `catch (Exception e) {}` | Use `assertThrows` |
| **Sleeps instead of assertions** | `Thread.sleep(5000);` | Use proper waits/timeouts |
| **Testing private methods** | Reflection hacks | Test through public API |

**12. Summary: Assertion Best Practices**

```java
@Test
@DisplayName("Complete example of good assertion practices")
void testGoodAssertions() {
    // 1. Check prerequisites with simple assertions
    User user = userService.findUser(123);
    assertNotNull(user, "Test user must exist");

    // 2. Use assertAll for multiple validations
    assertAll("User validation",
        () -> assertEquals("john@test.com", user.getEmail(),
            "Email should match expected"),
        () -> assertTrue(user.isActive(), 
            "User should be active"),
        () -> assertFalse(user.isBlocked(),
            "User should not be blocked")
    );

    // 3. Use appropriate assertions for different types
    List<Order> orders = user.getRecentOrders();
    assertNotNull(orders, "Orders list should not be null");
    assertTrue(orders.size() <= 10, 
        "Should have at most 10 recent orders");

    // 4. Test edge cases
    if (user.getAge() < 18) {
        assertFalse(user.canPurchase(),
            "Underage users should not be able to purchase");
    }

    // 5. Use exception assertions
    assertThrows(IllegalArgumentException.class,
        () -> userService.updateEmail(null),
        "Should throw when updating with null email"
    );
}
```

**Key Takeaway:**

Good assertions are the difference between flaky, hard-to-debug tests and reliable, maintainable test suites. Invest time in writing clear, focused assertions with meaningful messages that will help you quickly identify and fix issues when they arise.

**Running the Same Test Logic with Different Data**

Parameterized tests allow you to run the same test method multiple times with different input values. This is a cornerstone of data-driven testing and one of the most powerful features in JUnit 5.

**The Problem Parameterized Tests Solve:**

Without parameterized tests, you'd need to write separate test methods for each test case:

```java
// BAD - Code duplication
class CalculatorTest {

    @Test
    void testAddition_2and3() {
        assertEquals(5, calculator.add(2, 3));
    }

    @Test
    void testAddition_5and7() {
        assertEquals(12, calculator.add(5, 7));
    }

    @Test
    void testAddition_negativeNumbers() {
        assertEquals(-2, calculator.add(3, -5));
    }

    @Test
    void testAddition_zero() {
        assertEquals(5, calculator.add(5, 0));
    }
    // More and more tests...
}
```

**The Parameterized Solution:**

```java
// GOOD - Single test with multiple data sets
class CalculatorTest {

    @ParameterizedTest
    @ValueSource(ints = {2, 5, 3, 10, 0, -5})
    void testAddition(int number) {
        // Single test logic runs for each number
        assertEquals(number + 5, calculator.add(number, 5));
    }
}
```

**Benefits of Parameterized Tests:**

| Benefit | Description |
|---------|-------------|
| **Reduced Code Duplication** | One test method instead of many |
| **Increased Coverage** | Easy to add more test cases |
| **Better Maintenance** | Change logic in one place |
| **Clearer Intent** | Data separated from test logic |
| **Comprehensive Testing** | Test edge cases systematically |
| **Easier to Read** | Test data is clearly visible |

**JUnit 5 Parameterized Test Features:**

JUnit 5 provides a rich set of annotations for supplying arguments:

```
JUnit 5 Parameterized Tests
├── Simple Value Sources
│   ├── @ValueSource (primitives, strings, classes)
│   ├── @NullSource (null values)
│   └── @EmptySource (empty strings/collections)
├── Tabular Data Sources
│   ├── @CsvSource (comma-separated values)
│   ├── @CsvFileSource (external CSV files)
│   └── @MethodSource (custom provider methods)
├── Enum Sources
│   └── @EnumSource (enum constants)
├── Field Sources
│   └── @ArgumentsSource (custom providers)
└── Composite Sources
    └── Combining multiple sources
```

**Basic Setup:**

To use parameterized tests, you need the `junit-jupiter-params` dependency (included in `junit-jupiter` aggregator):

```xml
<dependency>
    <groupId>org.junit.jupiter</groupId>
    <artifactId>junit-jupiter-params</artifactId>
    <version>5.10.2</version>
    <scope>test</scope>
</dependency>
```

**Simple Example:**

```java
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;

class StringUtilsTest {

    @ParameterizedTest
    @ValueSource(strings = {"racecar", "radar", "able was I ere I saw elba"})
    void isPalindrome_shouldReturnTrueForPalindromes(String candidate) {
        assertTrue(StringUtils.isPalindrome(candidate), 
            () -> candidate + " should be a palindrome");
    }

    @ParameterizedTest
    @ValueSource(strings = {"hello", "world", "junit"})
    void isPalindrome_shouldReturnFalseForNonPalindromes(String candidate) {
        assertFalse(StringUtils.isPalindrome(candidate), 
            () -> candidate + " should not be a palindrome");
    }
}
```

questions.answer:
**Mastering @ValueSource:**

`@ValueSource` is the simplest way to provide arguments to parameterized tests. It supports arrays of primitive types, strings, and classes.

**Supported Types:**

- `ints` - for int primitives
- `longs` - for long primitives
- `doubles` - for double primitives
- `floats` - for float primitives
- `shorts` - for short primitives
- `bytes` - for byte primitives
- `chars` - for char primitives
- `booleans` - for boolean primitives
- `strings` - for String objects
- `classes` - for Class objects

**Basic Examples:**

```java
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;

class ValueSourceExamplesTest {

    @ParameterizedTest
    @ValueSource(ints = {1, 2, 3, 4, 5})
    void testWithInts(int number) {
        assertTrue(number > 0);
        assertTrue(number < 6);
    }

    @ParameterizedTest
    @ValueSource(longs = {10L, 20L, 30L, 40L, 50L})
    void testWithLongs(long value) {
        assertTrue(value % 10 == 0);
    }

    @ParameterizedTest
    @ValueSource(doubles = {1.5, 2.7, 3.14, 4.0, 5.5})
    void testWithDoubles(double value) {
        assertTrue(value > 0);
        assertTrue(value < 10);
    }

    @ParameterizedTest
    @ValueSource(strings = {"Hello", "World", "JUnit", "Test"})
    void testWithStrings(String text) {
        assertNotNull(text);
        assertTrue(text.length() > 0);
    }

    @ParameterizedTest
    @ValueSource(booleans = {true, false, true, false})
    void testWithBooleans(boolean flag) {
        // Test with both true and false
        assertNotNull(flag);
    }

    @ParameterizedTest
    @ValueSource(chars = {'a', 'b', 'c', 'd', 'e'})
    void testWithChars(char letter) {
        assertTrue(letter >= 'a' && letter <= 'e');
    }
}
```

**Testing Edge Cases with @NullSource and @EmptySource:**

```java
class NullAndEmptyTests {

    @ParameterizedTest
    @NullSource
    void testWithNull(String value) {
        assertNull(value);
        assertThrows(NullPointerException.class, 
            () -> value.length());
    }

    @ParameterizedTest
    @EmptySource
    void testWithEmptyString(String value) {
        assertEquals("", value);
        assertEquals(0, value.length());
    }

    @ParameterizedTest
    @NullAndEmptySource
    void testWithNullOrEmpty(String value) {
        // Runs with both null and empty
        assertTrue(value == null || value.isEmpty());
    }

    @ParameterizedTest
    @ValueSource(strings = {"  ", "\t", "\n"})
    @NullAndEmptySource
    void testBlankStrings(String value) {
        // Combines null, empty, and whitespace
        assertTrue(value == null || value.trim().isEmpty());
    }
}
```

**Combining Multiple Value Sources (not directly possible - need separate tests):**

```java
class CombinedSourcesTest {

    // Can't combine multiple @ValueSource annotations
    // Instead, use separate test methods or other sources

    @ParameterizedTest
    @ValueSource(ints = {1, 2, 3})
    void testWithInts(int value) {
        // Test with ints
    }

    @ParameterizedTest
    @ValueSource(ints = {4, 5, 6})
    void testWithMoreInts(int value) {
        // Test with more ints
    }
}
```

**Practical Example: Testing a Validation Method**

```java
class EmailValidatorTest {

    private EmailValidator validator = new EmailValidator();

    @ParameterizedTest
    @ValueSource(strings = {
        "user@example.com",
        "first.last@example.co.uk",
        "user+tag@example.com",
        "123@example.com",
        "user-name@example.org"
    })
    void shouldValidateValidEmails(String email) {
        assertTrue(validator.isValid(email),
            () -> email + " should be valid");
    }

    @ParameterizedTest
    @ValueSource(strings = {
        "user@",
        "@example.com",
        "user@example",
        "user.example.com",
        "user@.com",
        "user@example.",
        "user name@example.com"
    })
    @NullAndEmptySource
    void shouldRejectInvalidEmails(String email) {
        assertFalse(validator.isValid(email),
            () -> email + " should be invalid");
    }
}
```

**Practical Example: Testing a Calculator with Edge Cases**

```java
class CalculatorParameterizedTest {

    private Calculator calculator = new Calculator();

    @ParameterizedTest
    @ValueSource(ints = {0, 1, 2, 5, 10, 100, Integer.MAX_VALUE})
    void additionWithZeroShouldReturnSameNumber(int number) {
        assertEquals(number, calculator.add(number, 0));
        assertEquals(number, calculator.add(0, number));
    }

    @ParameterizedTest
    @ValueSource(ints = {1, 2, 3, 4, 5})
    void factorialShouldReturnPositive(int n) {
        long result = calculator.factorial(n);
        assertTrue(result > 0);
    }

    @ParameterizedTest
    @ValueSource(ints = {-1, -2, -5, -10})
    void factorialShouldThrowForNegative(int n) {
        assertThrows(IllegalArgumentException.class,
            () -> calculator.factorial(n));
    }
}
```

**Display Names for Parameterized Tests:**

```java
class DisplayNameExamplesTest {

    @ParameterizedTest(name = "Test with value {0}")
    @ValueSource(ints = {1, 2, 3})
    void testWithSimpleDisplayName(int value) {
        // Report shows: Test with value 1
        //              Test with value 2
        //              Test with value 3
    }

    @ParameterizedTest(name = "{index} => input: {0}, expected: {1}")
    @CsvSource({
        "1, 1",
        "2, 4",
        "3, 9"
    })
    void testWithDetailedDisplayName(int input, int expected) {
        // Report shows: 1 => input: 1, expected: 1
        //              2 => input: 2, expected: 4
        //              3 => input: 3, expected: 9
    }

    @ParameterizedTest(name = "Test #{index}: {arguments}")
    @ValueSource(strings = {"apple", "banana", "cherry"})
    void testWithArgumentsDisplay(String fruit) {
        // Report shows: Test #1: apple
        //               Test #2: banana
        //               Test #3: cherry
    }
}
```

**Placeholders for Display Names:**

| Placeholder | Description | Example |
|-------------|-------------|---------|
| `{index}` | Current invocation index (1-based) | `{index}` → `1` |
| `{arguments}` | Complete comma-separated arguments | `{arguments}` → `1, 2, 3` |
| `{0}`, `{1}`, ... | Individual argument values | `{0} + {1} = {2}` |
| `{displayName}` | Test display name | `{displayName}` → `testAddition` |

content.explanation:
**Testing with Multiple Parameters**

When you need to pass multiple arguments to your test method, `@CsvSource` and `@CsvFileSource` are the perfect solutions.

**1. @CsvSource - Inline CSV Data**

`@CsvSource` allows you to define tabular data directly in the annotation.

```java
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import static org.junit.jupiter.api.Assertions.*;

class CsvSourceExamplesTest {

    @ParameterizedTest
    @CsvSource({
        "1, 2, 3",
        "2, 3, 5",
        "3, 5, 8",
        "10, 20, 30"
    })
    void testAddition(int a, int b, int expected) {
        assertEquals(expected, a + b,
            () -> String.format("%d + %d should equal %d", a, b, expected));
    }

    @ParameterizedTest
    @CsvSource({
        "apple, 1.99, 5",
        "banana, 0.99, 3",
        "orange, 1.49, 2",
        "mango, 2.99, 1"
    })
    void testProductTotal(String product, double price, int quantity) {
        double total = price * quantity;
        assertTrue(total > 0);

        // Verify total calculation
        assertEquals(price * quantity, total, 0.001);
    }
}
```

**Handling Different Data Types:**

