```java
class UserRegistrationCsvTest {

    private UserService userService = new UserService();

    @ParameterizedTest
    @CsvFileSource(resources = "/user-data.csv", numLinesToSkip = 1)
    void testUserRegistration(String email, String name, int age, boolean valid) {
        if (valid) {
            User user = userService.registerUser(email, name, age);
            assertAll("Valid user",
                () -> assertNotNull(user),
                () -> assertEquals(email, user.getEmail()),
