**Best Practices for CSV Sources:**

| Practice | Example | Benefit |
|----------|---------|---------|
| **Skip header lines** | `numLinesToSkip = 1` | Use headers for documentation |
| **Handle nulls explicitly** | `nullValues = {"null"}` | Clear representation |
| **Use meaningful column names** | Headers in CSV | Self-documenting data |
| **Keep CSV files in resources** | `src/test/resources/` | Standard location |
| **Version control CSV files** | Commit with code | Data is tracked |
| **Document data format** | Comments in CSV | Team understanding |
| **Use appropriate delimiters** | Avoid commas in data | Prevent parsing errors |
| **Limit file size** | Split large files | Maintainability |

**Comprehensive Enum Testing**

`@EnumSource` allows you to run parameterized tests with enum constants, making it perfect for testing code that behaves differently for each enum value.

**Basic EnumSource Usage:**

```java
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import java.time.DayOfWeek;
import java.time.Month;

class EnumSourceBasicTest {

    @ParameterizedTest
    @EnumSource(DayOfWeek.class)
    void testAllDays(DayOfWeek day) {
        assertNotNull(day);
        assertTrue(day.toString().length() > 0);
    }

    @ParameterizedTest
    @EnumSource(Month.class)
    void testAllMonths(Month month) {
        assertTrue(month.getValue() >= 1 && month.getValue() <= 12);
    }
}
```

**Filtering Enum Values:**

```java
import org.junit.jupiter.params.provider.EnumSource.Mode;

class EnumFilteringTest {

    enum Status {
        PENDING, PROCESSING, COMPLETED, FAILED, CANCELLED, REFUNDED
    }

    @ParameterizedTest
    @EnumSource(value = Status.class, names = {"PENDING", "PROCESSING"})
    void testIncompleteStatuses(Status status) {
        assertTrue(status == Status.PENDING || status == Status.PROCESSING);
    }

    @ParameterizedTest
    @EnumSource(value = Status.class, names = {"COMPLETED", "FAILED"})
    void testTerminalStatuses(Status status) {
        assertTrue(status == Status.COMPLETED || status == Status.FAILED);
    }

    @ParameterizedTest
    @EnumSource(value = Status.class, mode = Mode.EXCLUDE, names = {"PENDING"})
    void testAllExceptPending(Status status) {
        assertNotEquals(Status.PENDING, status);
    }

    @ParameterizedTest
    @EnumSource(value = Status.class, mode = Mode.MATCH_ALL, names = ".*ED$")
    void testStatusesEndingWithED(Status status) {
        assertTrue(status.name().endsWith("ED"));
    }
}
```

**Practical Example: Testing Payment Processing**

```java
class PaymentProcessorTest {

    enum PaymentMethod {
        CREDIT_CARD(true),
        DEBIT_CARD(true),
        PAYPAL(true),
        BITCOIN(true),
        CASH_ON_DELIVERY(false),
        CHECK(false);

        private final boolean requiresOnline;

        PaymentMethod(boolean requiresOnline) {
            this.requiresOnline = requiresOnline;
        }

        boolean requiresOnline() {
            return requiresOnline;
        }
    }

    private PaymentProcessor processor = new PaymentProcessor();

    @ParameterizedTest
    @EnumSource(value = PaymentMethod.class, names = {"CREDIT_CARD", "DEBIT_CARD", "PAYPAL", "BITCOIN"})
    void onlinePaymentMethodsShouldRequireConnection(PaymentMethod method) {
        assertTrue(method.requiresOnline());
        assertTrue(processor.canProcessOnline(method));
    }

    @ParameterizedTest
    @EnumSource(value = PaymentMethod.class, names = {"CASH_ON_DELIVERY", "CHECK"})
    void offlinePaymentMethodsShouldNotRequireConnection(PaymentMethod method) {
        assertFalse(method.requiresOnline());
        assertFalse(processor.canProcessOnline(method));
    }

    @ParameterizedTest
    @EnumSource(value = PaymentMethod.class, mode = Mode.EXCLUDE, names = {"BITCOIN"})
    void allExceptBitcoinShouldSupportCurrencyUSD(PaymentMethod method) {
        assertTrue(processor.supportsCurrency(method, Currency.USD));
    }
}
```

**Using Enum with Multiple Modes:**

```java
class ComplexEnumTest {

    enum Priority {
        LOW(1), MEDIUM(2), HIGH(3), CRITICAL(4), BLOCKER(5);

        private final int level;

        Priority(int level) {
            this.level = level;
        }

        boolean isHighOrHigher() {
            return level >= 3;
        }
    }

    @ParameterizedTest
    @EnumSource(mode = Mode.INCLUDE, names = {"HIGH", "CRITICAL", "BLOCKER"})
    void highPriorityShouldBeProcessedImmediately(Priority priority) {
        assertTrue(priority.isHighOrHigher());
    }

    @ParameterizedTest
    @EnumSource(mode = Mode.EXCLUDE, names = {"LOW", "MEDIUM"})
    void excludeLowAndMediumShouldIncludeHighAndAbove(Priority priority) {
        assertTrue(priority.isHighOrHigher());
    }

    @ParameterizedTest
    @EnumSource(mode = Mode.MATCH_ALL, names = "^[A-Z]{4,}$")
    void priorityWithLongNamesShouldBeRare(Priority priority) {
        // Tests priorities with names of length >= 4 (CRITICAL, BLOCKER)
        assertTrue(priority.name().length() >= 4);
    }
}
```

**Combining EnumSource with Display Names:**

```java
class EnumDisplayNameTest {

    enum Color {
        RED, GREEN, BLUE, YELLOW, PURPLE, ORANGE
    }

    @ParameterizedTest(name = "Primary color: {0}")
    @EnumSource(value = Color.class, names = {"RED", "GREEN", "BLUE"})
    void testPrimaryColors(Color color) {
        assertTrue(isPrimary(color));
    }

    @ParameterizedTest(name = "Secondary color: {0}")
    @EnumSource(value = Color.class, names = {"YELLOW", "PURPLE", "ORANGE"})
    void testSecondaryColors(Color color) {
        assertTrue(isSecondary(color));
    }

    private boolean isPrimary(Color color) {
        return color == Color.RED || color == Color.GREEN || color == Color.BLUE;
    }

    private boolean isSecondary(Color color) {
        return !isPrimary(color);
    }
}
```

**Maximum Flexibility for Complex Data**

When built-in sources aren't enough, `@MethodSource` lets you create custom provider methods that can generate any kind of test data.

**Basic MethodSource Example:**

```java
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import java.util.stream.Stream;

class MethodSourceBasicTest {

    @ParameterizedTest
    @MethodSource("stringProvider")
    void testWithSimpleMethodSource(String argument) {
        assertNotNull(argument);
    }

    static Stream<String> stringProvider() {
        return Stream.of("apple", "banana", "cherry");
    }
}
```

**Return Types for MethodSource:**

MethodSource methods can return:
- `Stream<T>`
- `Iterable<T>`
- `Iterator<T>`
- `T[]` (array)

```java
class MethodSourceReturnTypesTest {

    @ParameterizedTest
    @MethodSource("streamProvider")
    void testWithStream(String value) {
        assertNotNull(value);
    }

    @ParameterizedTest
    @MethodSource("listProvider")
    void testWithList(String value) {
        assertNotNull(value);
    }

    @ParameterizedTest
    @MethodSource("arrayProvider")
    void testWithArray(String value) {
        assertNotNull(value);
    }

    static Stream<String> streamProvider() {
        return Stream.of("one", "two", "three");
    }

    static List<String> listProvider() {
        return Arrays.asList("a", "b", "c");
    }

    static String[] arrayProvider() {
        return new String[]{"x", "y", "z"};
    }
}
```

**Multiple Arguments with MethodSource:**

For multiple arguments, use `Arguments` objects:

```java
import org.junit.jupiter.params.provider.Arguments;
import java.util.stream.Stream;

class MultiArgumentMethodSourceTest {

