**External Data Sources in MethodSource:**

```java
class ExternalDataSourceTest {

    @ParameterizedTest
    @MethodSource("csvDataProvider")
    void testFromCSV(String name, int age, String city) {
        assertNotNull(name);
        assertTrue(age > 0);
        assertNotNull(city);
    }

    static Stream<Arguments> csvDataProvider() throws IOException {
        List<Arguments> args = new ArrayList<>();

        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(
                    ExternalDataSourceTest.class.getResourceAsStream("/data.csv")))) {
            String line;
            reader.readLine(); // Skip header
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(",");
                args.add(Arguments.of(parts[0], Integer.parseInt(parts[1]), parts[2]));
            }
        }

        return args.stream();
    }

    @ParameterizedTest
    @MethodSource("dbDataProvider")
    void testFromDatabase(String product, double price) {
        assertNotNull(product);
        assertTrue(price > 0);
    }

    static Stream<Arguments> dbDataProvider() throws SQLException {
        List<Arguments> args = new ArrayList<>();

        try (Connection conn = DriverManager.getConnection("jdbc:h2:mem:test");
             Statement stmt = conn.createStatement()) {
            ResultSet rs = stmt.executeQuery("SELECT product, price FROM test_data");
            while (rs.next()) {
                args.add(Arguments.of(rs.getString("product"), rs.getDouble("price")));
            }
        }

        return args.stream();
    }
}
```

