    private Connection connection;

    @BeforeAll
    static void setupDataSource() {
        // Expensive - create connection pool once
        HikariConfig config = new HikariConfig();
        config.setJdbcUrl("jdbc:mysql://localhost/testdb");
        dataSource = new HikariDataSource(config);
    }

    @BeforeEach
    void beginTransaction() throws SQLException {
        // Cheap - get connection and start transaction
        connection = dataSource.getConnection();
        connection.setAutoCommit(false);
    }

    @Test
    void testInsert() throws SQLException {
        try (Statement stmt = connection.createStatement()) {
            int result = stmt.executeUpdate("INSERT INTO users (name) VALUES ('test')");
            assertEquals(1, result);
        }
    }

    @Test
    void testUpdate() throws SQLException {
        try (Statement stmt = connection.createStatement()) {
            int result = stmt.executeUpdate("UPDATE users SET name='updated' WHERE id=1");
            assertTrue(result >= 0);
        }
    }

    @AfterEach
    void rollbackTransaction() throws SQLException {
        if (connection != null) {
            connection.rollback();  // Each test's changes are rolled back
            connection.close();
        }
    }

    @AfterAll
    static void closeDataSource() {
        if (dataSource != null) {
            ((HikariDataSource) dataSource).close();
        }
    }
}
```

