**Comprehensive Exception Validation**

Sometimes just knowing an exception was thrown isn't enough. You need to validate the message, cause, and any custom properties.

**Validating Exception Messages:**

```java
class MessageValidationTest {

    @Test
    void shouldThrowWithExactMessage() {
        Exception exception = assertThrows(IllegalArgumentException.class,
            () -> new BankAccount().withdraw(-100));

        assertEquals("Amount must be positive", exception.getMessage());
    }

    @Test
    void shouldThrowWithMessageContainingText() {
        Exception exception = assertThrows(ValidationException.class,
            () -> validator.validateEmail("invalid"));

        assertTrue(exception.getMessage().contains("invalid"));
        assertTrue(exception.getMessage().contains("email"));
    }

    @Test
    void shouldThrowWithMessageMatchingPattern() {
        Exception exception = assertThrows(NumberFormatException.class,
            () -> Integer.parseInt("abc123"));

        assertTrue(exception.getMessage().matches("For input string: \".*\""));
    }
}
```

**Validating Exception Causes:**

```java
class CauseValidationTest {

    @Test
    void shouldWrapExceptionWithCause() {
        DataAccessException exception = assertThrows(DataAccessException.class,
            () -> repository.findUser(1));

        assertNotNull(exception.getCause());
        assertTrue(exception.getCause() instanceof SQLException);
        assertEquals("Connection timeout", exception.getCause().getMessage());
    }

    @Test
    void shouldChainMultipleExceptions() {
        ServiceException exception = assertThrows(ServiceException.class,
            () -> service.processOrder(invalidOrder));

        // Check exception chain
        Throwable cause = exception.getCause();
        assertTrue(cause instanceof ValidationException);

        Throwable rootCause = cause.getCause();
        assertTrue(rootCause instanceof IllegalArgumentException);
        assertEquals("Order ID cannot be null", rootCause.getMessage());
    }
}
```

**Validating Custom Exception Properties:**

```java
// Custom exception with properties
class BusinessException extends RuntimeException {
    private final String errorCode;
    private final String field;
    private final LocalDateTime timestamp;

    public BusinessException(String message, String errorCode, String field) {
        super(message);
        this.errorCode = errorCode;
        this.field = field;
        this.timestamp = LocalDateTime.now();
    }

    public String getErrorCode() { return errorCode; }
    public String getField() { return field; }
    public LocalDateTime getTimestamp() { return timestamp; }
}

class CustomPropertiesTest {

    @Test
    void shouldThrowBusinessExceptionWithCorrectProperties() {
        BusinessException exception = assertThrows(BusinessException.class,
            () -> service.updateUser(null, "John"));

        assertAll("Business exception properties",
            () -> assertEquals("INVALID_INPUT", exception.getErrorCode()),
            () -> assertEquals("userId", exception.getField()),
            () -> assertNotNull(exception.getTimestamp()),
            () -> assertTrue(exception.getMessage().contains("null"))
        );
    }

    @Test
    void shouldIncludeAdditionalContext() {
        ValidationException exception = assertThrows(ValidationException.class,
            () -> validator.validateOrder(order));

        // Check that exception contains validation errors
        List<String> errors = exception.getValidationErrors();
        assertAll("Validation errors",
            () -> assertFalse(errors.isEmpty()),
            () -> assertTrue(errors.contains("Order date cannot be in past")),
            () -> assertTrue(errors.contains("Total must be positive"))
        );
    }
}
