    }

    @Test
    void createUser_emptyEmail_throwsException() {
        Exception ex = assertThrows(IllegalArgumentException.class,
            () -> service.createUser("", "John", 30));
        assertEquals("Email is required", ex.getMessage());
    }

    @ParameterizedTest
    @ValueSource(ints = {17, 151, 0, -1, 200})
    void createUser_invalidAge_throwsException(int age) {
        Exception ex = assertThrows(IllegalArgumentException.class,
            () -> service.createUser("john@test.com", "John", age));
