**Fine-Grained Test Selection**

Tags allow you to categorize tests and include or exclude them in suites.

**Tagging Test Methods:**

```java
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

class TaggedTestClass {

    @Test
    @Tag("smoke")
    @Tag("critical")
    void smokeTest() { }

    @Test
    @Tag("regression")
    void regressionTest() { }

    @Test
    @Tag("slow")
    @Tag("performance")
    void performanceTest() { }

    @Test
    @Tag("database")
    @Tag("integration")
    void databaseTest() { }
}
```

**Tagging Test Classes:**

```java
@Tag("unit")
class UnitTestClass {
    @Test void test1() { }
    @Test void test2() { }
}

@Tag("integration")
class IntegrationTestClass {
    @Test void test1() { }
    @Test void test2() { }
}
```

**Using Tags in Test Suites:**

```java
import org.junit.platform.suite.api.*;

@Suite
@SelectPackages("com.example")
@IncludeTags({"smoke", "critical"})
@ExcludeTags({"slow", "flaky"})
public class TagFilteredTestSuite {
    // Runs only tests tagged with smoke OR critical
    // Excludes tests tagged with slow OR flaky
}

@Suite
@SelectPackages("com.example")
@IncludeTags(value = {"unit", "fast"}, type = IncludeTags.AND)
@ExcludeTags("broken")
public class AndFilterTestSuite {
    // Runs tests tagged with BOTH unit AND fast
}

@Suite
@SelectPackages("com.example")
@IncludeTags("database")
@IncludeClassNamePatterns({".*IntegrationTest"})
public class DatabaseIntegrationTestSuite {
    // Runs integration tests that are also tagged with database
}
```

**Complex Tag Expressions:**

```java
// Run tests that are either smoke or critical, but not slow
@Suite
@SelectPackages("com.example")
@IncludeTags({"smoke", "critical"})
@ExcludeTags("slow")
public class SmokeAndCriticalSuite {}

// Run tests that are both integration and database
@Suite
@SelectPackages("com.example")
@IncludeTags(value = {"integration", "database"}, type = IncludeTags.AND)
public class IntegrationDatabaseSuite {}

// Run tests that are api tests, but not deprecated or broken
@Suite
@SelectPackages("com.example.api")
@IncludeTags("api")
@ExcludeTags({"deprecated", "broken"})
public class ActiveApiTestSuite {}
```

