**Jenkinsfile for Microservices Testing:**

```groovy
pipeline {
    agent none

    environment {
        DOCKER_REGISTRY = 'registry.company.com'
        TEST_ENV = 'staging'
        REPORT_DIR = 'test-reports'
    }

    stages {
        stage('Build and Deploy Services') {
            parallel {
                stage('Build Service A') {
                    agent { label 'builder' }
                    steps {
                        dir('services/service-a') {
                            sh 'docker build -t ${DOCKER_REGISTRY}/service-a:${BUILD_NUMBER} .'
                            sh 'docker push ${DOCKER_REGISTRY}/service-a:${BUILD_NUMBER}'
                            sh 'kubectl set image deployment/service-a service-a=${DOCKER_REGISTRY}/service-a:${BUILD_NUMBER}'
                        }
                    }
                }
                stage('Build Service B') {
                    agent { label 'builder' }
                    steps {
                        dir('services/service-b') {
                            sh 'docker build -t ${DOCKER_REGISTRY}/service-b:${BUILD_NUMBER} .'
                            sh 'docker push ${DOCKER_REGISTRY}/service-b:${BUILD_NUMBER}'
                            sh 'kubectl set image deployment/service-b service-b=${DOCKER_REGISTRY}/service-b:${BUILD_NUMBER}'
                        }
                    }
                }
            }
        }

        stage('Wait for Deployment') {
            agent { label 'builder' }
            steps {
                sh 'kubectl rollout status deployment/service-a'
                sh 'kubectl rollout status deployment/service-b'
                sh 'sleep 10'  // Give services time to warm up
            }
        }

        stage('Run Service Unit Tests') {
            parallel {
                stage('Service A Unit Tests') {
                    agent { label 'test-runner' }
                    steps {
                        dir('services/service-a') {
                            sh 'mvn clean test -Dgroups=unit'
                        }
                    }
                    post {
                        always {
                            junit 'services/service-a/target/surefire-reports/*.xml'
                        }
                    }
                }
                stage('Service B Unit Tests') {
                    agent { label 'test-runner' }
                    steps {
                        dir('services/service-b') {
                            sh 'mvn clean test -Dgroups=unit'
                        }
                    }
                    post {
                        always {
                            junit 'services/service-b/target/surefire-reports/*.xml'
                        }
                    }
                }
            }
        }

        stage('Integration Tests') {
            agent { label 'test-runner' }
            steps {
                dir('tests/integration') {
                    sh """
                        mvn clean test \
                            -Dgroups=integration \
                            -Dservice-a.url=http://service-a:8080 \
                            -Dservice-b.url=http://service-b:8080 \
                            -Denvironment=${TEST_ENV}
                    """
                }
            }
            post {
                always {
                    junit 'tests/integration/target/surefire-reports/*.xml'
                }
            }
        }

        stage('End-to-End Tests') {
            agent { label 'test-runner' }
            when { branch 'main' }
            steps {
                dir('tests/e2e') {
                    sh """
                        mvn clean test \
                            -Dgroups=e2e,critical \
                            -Dapp.url=https://staging.company.com
                    """
                }
            }
            post {
                always {
                    junit 'tests/e2e/target/surefire-reports/*.xml'
                    publishHTML([
                        reportDir: 'tests/e2e/target/site',
                        reportFiles: 'surefire-report.html',
                        reportName: 'E2E Test Report'
                    ])
                }
            }
        }
    }

    post {
        always {
            // Send summary to Slack
            def summary = createTestSummary()
            slackSend(
                color: currentBuild.result == 'SUCCESS' ? 'good' : 'danger',
                message: "${currentBuild.result}: ${env.JOB_NAME} #${env.BUILD_NUMBER}\n${summary}",
                channel: '#ci-cd'
            )
        }

        failure {
            // Trigger rollback if tests fail
            sh 'kubectl rollout undo deployment/service-a'
            sh 'kubectl rollout undo deployment/service-b'
        }
    }
}

def createTestSummary() {
    def summary = ""
    def reports = findFiles(glob: '**/target/surefire-reports/TEST-*.xml')

    reports.each { report ->
        def content = readFile(report.path)
        def total = (content =~ /tests="(\d+)"/).find() ? (content =~ /tests="(\d+)"/)[0][1] : 0
        def failures = (content =~ /failures="(\d+)"/).find() ? (content =~ /failures="(\d+)"/)[0][1] : 0
        def errors = (content =~ /errors="(\d+)"/).find() ? (content =~ /errors="(\d+)"/)[0][1] : 0

        def serviceName = report.path.split('/')[0]
        summary += "${serviceName}: ${total} tests, ${failures} failures, ${errors} errors\n"
    }

    return summary
}
